   296	function getAllExpensesToHoldIfApplicable(report?: Report, reportActions?: ReportAction[]) {
   297	    if (!report || !reportActions || !hasOnlyHeldExpenses(report?.reportID)) {
   298	        return [];
   299	    }
   300	
   301	    return reportActions?.filter((action) => isMoneyRequestAction(action) && action.childType === CONST.REPORT.TYPE.CHAT && canHoldUnholdReportAction(action).canUnholdRequest);
   302	}
   303	
   304	function getReportPrimaryAction(params: GetReportPrimaryActionParams): ValueOf<typeof CONST.REPORT.PRIMARY_ACTIONS> | '' {
   305	    const {report, reportTransactions, violations, policy, reportNameValuePairs, reportActions, isChatReportArchived, chatReport, invoiceReceiverPolicy} = params;
   306	
   307	    const isPayActionWithAllExpensesHeld = isPrimaryPayAction(report, policy, reportNameValuePairs, isChatReportArchived) && hasOnlyHeldExpenses(report?.reportID);
   308	
   309	    if (isAddExpenseAction(report, reportTransactions, isChatReportArchived)) {
   310	        return CONST.REPORT.PRIMARY_ACTIONS.ADD_EXPENSE;
   311	    }
   312	
   313	    if (isMarkAsCashAction(report, reportTransactions, violations, policy)) {
   314	        return CONST.REPORT.PRIMARY_ACTIONS.MARK_AS_CASH;
   315	    }
   316	
   317	    if (isReviewDuplicatesAction(report, reportTransactions, policy)) {
   318	        return CONST.REPORT.PRIMARY_ACTIONS.REVIEW_DUPLICATES;
   319	    }
   320	
   321	    if (isRemoveHoldAction(report, chatReport, reportTransactions) || isPayActionWithAllExpensesHeld) {
   322	        return CONST.REPORT.PRIMARY_ACTIONS.REMOVE_HOLD;
   323	    }
   324	
   325	    if (isSubmitAction(report, reportTransactions, policy, reportNameValuePairs, reportActions)) {
   326	        return CONST.REPORT.PRIMARY_ACTIONS.SUBMIT;
   327	    }
   328	
   329	    if (isApproveAction(report, reportTransactions, policy)) {
   330	        return CONST.REPORT.PRIMARY_ACTIONS.APPROVE;
   331	    }
   332	
   333	    if (isPrimaryPayAction(report, policy, reportNameValuePairs, isChatReportArchived, invoiceReceiverPolicy)) {
   334	        return CONST.REPORT.PRIMARY_ACTIONS.PAY;
   335	    }
   336	
   337	    if (isExportAction(report, policy, reportActions)) {
   338	        return CONST.REPORT.PRIMARY_ACTIONS.EXPORT_TO_ACCOUNTING;
   339	    }
   340	
   341	    if (getAllExpensesToHoldIfApplicable(report, reportActions).length) {
   342	        return CONST.REPORT.PRIMARY_ACTIONS.REMOVE_HOLD;
   343	    }
   344	
   345	    return '';
   346	}
