   348	function isMarkAsCashActionForTransaction(parentReport: Report, violations: TransactionViolation[], policy?: Policy): boolean {
   349	    const hasPendingRTERViolation = hasPendingRTERViolationTransactionUtils(violations);
   350	
   351	    if (hasPendingRTERViolation) {
   352	        return true;
   353	    }
   354	
   355	    const shouldShowBrokenConnectionViolation = shouldShowBrokenConnectionViolationTransactionUtils(parentReport, policy, violations);
   356	
   357	    if (!shouldShowBrokenConnectionViolation) {
   358	        return false;
   359	    }
   360	
   361	    const isReportSubmitter = isCurrentUserSubmitter(parentReport);
   362	    const isReportApprover = isApproverUtils(policy, getCurrentUserAccountID());
   363	    const isAdmin = policy?.role === CONST.POLICY.ROLE.ADMIN;
   364	
   365	    return isReportSubmitter || isReportApprover || isAdmin;
   366	}
   367	
   368	function getTransactionThreadPrimaryAction(
   369	    transactionThreadReport: Report,
   370	    parentReport: Report,
   371	    reportTransaction: Transaction,
   372	    violations: TransactionViolation[],
   373	    policy?: Policy,
   374	): ValueOf<typeof CONST.REPORT.TRANSACTION_PRIMARY_ACTIONS> | '' {
   375	    if (isHoldCreator(reportTransaction, transactionThreadReport.reportID)) {
   376	        return CONST.REPORT.TRANSACTION_PRIMARY_ACTIONS.REMOVE_HOLD;
   377	    }
   378	
   379	    if (isReviewDuplicatesAction(parentReport, [reportTransaction], policy)) {
   380	        return CONST.REPORT.TRANSACTION_PRIMARY_ACTIONS.REVIEW_DUPLICATES;
   381	    }
   382	
   383	    if (isMarkAsCashActionForTransaction(parentReport, violations, policy)) {
   384	        return CONST.REPORT.TRANSACTION_PRIMARY_ACTIONS.MARK_AS_CASH;
   385	    }
   386	
   387	    return '';
   388	}
